  function leadTemperature(lead, nowMs) {
    const base = new Date(lead.created_at || Date.now()).getTime();
    const days = (nowMs - base) / 864e5;
    if (days < 3) return { label: "\u{1F525} Super hot", color: "#ef4444", days };
    if (days < 7) return { label: "\u{1F7E0} Hot", color: "#f97316", days };
    if (days < 14) return { label: "\u{1F7E1} Warm", color: "#f59e0b", days };
    if (days < 30) return { label: "\u{1F535} Cold", color: "#0ea5e9", days };
    return { label: "\u26AA Frio", color: "#a1a1aa", days };
  }
